{
  "framing_amenaza_social_citas_polemicas": {
    "definicion": "Es una técnica de encuadre que presenta un tema como una amenaza para la sociedad, apoyándose en citas controvertidas de figuras públicas para intensificar la percepción de riesgo y generar miedo o urgencia en el receptor.",
    "ejemplo": "Artículo de marzo 2024 en un diario español que, al hablar de inmigración, incluye la cita polémica de un político: \"La ola de migrantes pondrá en peligro nuestra forma de vida\" y construye el relato como una amenaza inminente.",
    "como_detectarla": [
      "Identificar un lenguaje alarmista que vincula el tema a un peligro social.",
      "Verificar la presencia de citas sensacionalistas o fuera de contexto de autoridades o expertos.",
      "Analizar si el enfoque destaca la amenaza por encima de datos objetivos y contextuales."
    ]
  },
  "framing_noticias_locales_culturales": {
    "definicion": "Consiste en presentar la información resaltando su dimensión local o cultural, enfatizando valores, tradiciones o identidades de una comunidad para crear mayor identificación y relevancia entre el público objetivo.",
    "ejemplo": "Cobertura del 15 de abril de 2024 sobre la Feria de Abril de Sevilla que destaca la música, el traje de flamenca y la comunidad sevillana, mientras apenas menciona el impacto económico del evento.",
    "como_detectarla": [
      "Observar un énfasis marcado en elementos geográficos, históricos o de identidad cultural.",
      "Detectar la minimización o exclusión de temas de interés más amplio (ej. economía, política).",
      "Evaluar el uso de vocabulario que refuerza orgullo o pertenencia local."
    ]
  },
  "omission_tema_relevante": {
    "definicion": "Es la práctica de excluir deliberadamente información o datos que son pertinentes para la comprensión completa del asunto, lo que puede distorsionar la percepción del lector al presentar una versión incompleta de la realidad.",
    "ejemplo": "Reportaje de febrero 2024 sobre cambio climático que ignora el informe del IPCC 2023, pese a que el documento contiene alertas críticas sobre el aumento del nivel del mar.",
    "como_detectarla": [
      "Comparar el contenido con fuentes externas que enumeren los hechos o datos relevantes.",
      "Buscar lagunas evidentes donde se esperaría información clave.",
      "Evaluar si la ausencia de esos datos altera significativamente la interpretación del tema."
    ]
  },
  "omission_deliberada_tema_IA": {
    "definicion": "Se trata de la exclusión intencional de referencias a la inteligencia artificial en la cobertura informativa, aun cuando la IA sea un componente central del asunto tratado, con el fin de dirigir la atención o evitar controversias.",
    "ejemplo": "Cobertura del evento de lanzamiento del iPhone 16 en septiembre 2024 que se centra únicamente en el diseño y la cámara, sin mencionar las nuevas capacidades de IA integradas en el dispositivo.",
    "como_detectarla": [
      "Identificar si el tema tratado tiene una relación conocida o esperada con la IA.",
      "Comprobar la ausencia de menciones a la IA en el texto pese a su relevancia.",
      "Revisar otros medios que sí aborden la dimensión IA para detectar la discrepancia."
    ]
  },
  "agenda_setting_centrado_politica_deporte": {
    "definicion": "Es la capacidad de los medios para influir en la importancia que el público asigna a ciertos asuntos, al dar mayor espacio y prominencia a temas como política y deporte, relegando a un segundo plano otras áreas de interés público.",
    "ejemplo": "Semana de noticias en EE. UU. (abril 2024) en la que los titulares principales fueron las elecciones primarias y los playoffs de la NBA, mientras que la cobertura de la inflación y la reforma sanitaria fue mínima.",
    "como_detectarla": [
      "Ordenar los temas según su posición (portada, tiempo de emisión, tamaño de artículo).",
      "Comparar esa jerarquía con indicadores externos de saliencia social (encuestas, índices de preocupación pública).",
      "Detectar patrones recurrentes de sobrerepresentación de política y deporte frente a otros temas."
    ]
  }
}
